import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily: interFamily } = loadInter();



export type LoadingSymbolProps = Record<string, any>;

const LoadingSymbol: React.FC<LoadingSymbolProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 5,
  loadingText = "Connecting",
  spinnerColor = "#ffffff",
  textColor = "#ffffff",
  spinnerScale = 1.0,
  shadowOpacity = 0.8,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Responsive scaling base logic (optimizing for 1080x1920 baseline)
  const baseMinDim = Math.min(width, height);
  const responsiveScale = (baseMinDim / 1080) * spinnerScale;

  // Text Logic
  const baseText = loadingText.replace(/\.+$/, ""); // Strip trailing dots to animate them purely
  const dotCount = Math.floor(frame / (fps * 0.5)) % 4; // Add a dot every 0.5 seconds
  const dots = ".".repeat(dotCount);

  // Entrance animations
  const textOpacity = interpolate(frame, [10, 25], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  const textY = interpolate(frame, [10, 25], [20 * responsiveScale, 0], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  const spinnerOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  const spinnerScaleIn = spring({
    frame,
    fps,
    config: { damping: 16, mass: 0.8 },
    durationInFrames: 30,
  });

  // Dual-layer shadow for deep contrast against complex video backgrounds
  const shadowFilter = `drop-shadow(0px ${8 * responsiveScale}px ${24 * responsiveScale}px rgba(0,0,0,${shadowOpacity})) drop-shadow(0px ${2 * responsiveScale}px ${6 * responsiveScale}px rgba(0,0,0,${shadowOpacity * 0.6}))`;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
        fontFamily: interFamily,
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          gap: `${48 * responsiveScale}px`,
        }}
      >
        {/* Text Area */}
        <div
          style={{
            opacity: textOpacity,
            transform: `translateY(${textY}px)`,
            fontSize: `${64 * responsiveScale}px`,
            fontWeight: 600,
            color: textColor,
            filter: shadowFilter,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
          }}
        >
          {/* This wrapper guarantees a fixed width based on maximum string length, preventing centering jitter */}
          <div style={{ position: "relative" }}>
            <span style={{ visibility: "hidden" }}>{baseText}...</span>
            <span
              style={{
                position: "absolute",
                left: 0,
                top: 0,
                whiteSpace: "pre",
              }}
            >
              {baseText}
              {dots}
            </span>
          </div>
        </div>

        {/* Spinner Area */}
        <div
          style={{
            opacity: spinnerOpacity,
            transform: `scale(${spinnerScaleIn})`,
            filter: shadowFilter,
          }}
        >
          <svg
            width={200 * responsiveScale}
            height={200 * responsiveScale}
            viewBox="0 0 100 100"
            style={{ overflow: "visible" }}
          >
            {Array.from({ length: 12 }).map((_, i) => {
              const rotation = i * 30;
              const rotationsPerSecond = 1.2;
              
              // Determine the current "head" position of the bright spinner streak
              const currentTickPosition = (frame / fps) * 12 * rotationsPerSecond;
              
              // Calculate continuous distance wrapping around the 12 ticks
              const distanceFloat = (currentTickPosition - i + 120) % 12;

              // Tail fades smoothly behind the head, sharply drops off in front
              const tickOpacity = interpolate(
                distanceFloat,
                [0, 1.5, 3, 6, 12],
                [1, 0.6, 0.2, 0.05, 0.05],
                { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
              );

              return (
                <rect
                  key={i}
                  x={50 - 3}
                  y={8}
                  width={6}
                  height={24}
                  rx={3}
                  fill={spinnerColor}
                  opacity={tickOpacity}
                  transform={`rotate(${rotation} 50 50)`}
                  style={{ transition: "none" }}
                />
              );
            })}
          </svg>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default LoadingSymbol;